// #6350: golden for the event-place work. Nothing about a stage may move except
// WHERE the timeline says things happened. Digest one: everything but the
// timeline (times, ranks, groups, incidents, passages). Digest two: the timeline
// without the place keys, so every event is still there, in the same order, with
// the same km (the engine's ordering key) and the same content.
// The baseline (test-data/placesGolden6350.json) was generated by this file run
// against a frozen checkout of the merge-base, never by the new code.
import { DIGEST_SEEDS, digestOf, frozenStageOutput, frozenStages, physicsOf } from "./oldRevisionDigests6199.ts";
import type { StageOutput } from "../types.ts";

export const GOLDEN_REVISIONS = ["official_times_v2", "official_times_v5", "s5_profiles_v2", "s5_profiles_v3"] as const;

/** The keys this work may touch: the place of an event, and the group an incident formed. */
export function timelineWithoutPlaces(output: StageOutput): unknown {
  return output.timeline.events.map((event) => {
    const { exact_km: _km, exact_time: _time, ...params } = event.params ?? {};
    if (event.type === "incident") delete params.group_id;
    return { ...event, params };
  });
}

export function placesGoldenDigests(): Record<string, Record<string, { physics: string; timeline: string }>> {
  const stages = frozenStages();
  const out: Record<string, Record<string, { physics: string; timeline: string }>> = {};
  for (const revision of GOLDEN_REVISIONS) {
    out[revision] = {};
    for (const seed of DIGEST_SEEDS) {
      for (const row of stages) {
        const output = frozenStageOutput(row, seed, revision);
        out[revision][`${row.profile_type}#${row.stage_number ?? 1}@${seed}`] = {
          physics: digestOf(physicsOf(output)),
          timeline: digestOf(timelineWithoutPlaces(output)),
        };
      }
    }
  }
  return out;
}
